<?php require_once __DIR__.'/config/db.php';$pdo=db();if(is_logged_in())redirect('account/');$title='Login | '.APP_NAME;$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf($_POST['csrf']??null)){$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM users WHERE email=? AND is_active=1 LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u&&$u['password_hash']&&password_verify($pass,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['role']=$u['role_slug'];$return=trim($_GET['return']??''); if($u['role_slug']==='customer' && $return && !preg_match('~^(https?:)?//~',$return)) redirect($return); redirect($u['role_slug']==='customer'?'account/':'admin/');}$error='Email or password is incorrect.';}include __DIR__.'/includes/header.php';?><section class="container auth"><div class="auth-card"><span class="eyebrow">WELCOME</span><h1>Continue to Aapki Grocery</h1><p>First-time customers can continue with Gmail. OAuth needs your Google Client ID in config.php.</p><a class="google-btn" href="<?=url('auth/google.php')?>">G&nbsp;&nbsp; Continue with Google / Gmail</a><?php if($error): ?><div class="alert"><?=e($error)?></div><?php endif; ?><div class="divider">or admin / local login</div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn btn-primary full">Login</button></form></div></section><?php include __DIR__.'/includes/footer.php';?>
